// ============================================================
// THĂM DÒ BÁO CÁO TÀI CHÍNH (để tự tính ROE = LNST/VCSH, Nợ/Vốn) - mã VNM
// Thử nhiều biến thể financial_statements / financial_models.
// ============================================================
const H = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json, text/plain, */*',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const sources = [
  { name: 'A. financial_models modelType:1', url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM~modelType:1&sort=reportDate:desc&size=4' },
  { name: 'B. financial_models modelType:2', url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM~modelType:2&sort=reportDate:desc&size=4' },
  { name: 'C. financial_models modelType:3', url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM~modelType:3&sort=reportDate:desc&size=4' },
  { name: 'D. financial_models note:TTM', url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM~note:TTM&sort=reportDate:desc&size=4' },
  { name: 'E. financial_statements ANNUAL', url: 'https://api-finfo.vndirect.com.vn/v4/financial_statements?q=code:VNM~reportType:ANNUAL&sort=fiscalDate:desc&size=4' },
  { name: 'F. financial_statements (tối giản)', url: 'https://api-finfo.vndirect.com.vn/v4/financial_statements?q=code:VNM&size=4' },
  { name: 'G. financial_models (tối giản)', url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM&sort=reportDate:desc&size=4' },
];

const results = [];
for (const s of sources) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: s.url, headers: H, json: false, timeout: 20000 });
    const body = typeof res === 'string' ? res : JSON.stringify(res);
    results.push({ source: s.name, status: '✅ SỐNG', sample: body.slice(0, 800) });
  } catch (e) {
    results.push({ source: s.name, status: '❌ ' + (e.message || String(e)), sample: '' });
  }
}

return results.map(r => ({ json: r }));
